-- Global mineral commodity statistics -- production, reserves, and US import reliance by country, commodity, and year (305K rows).
-- Auto-generated by scripts/gen_evidence_pages.py: 304,632 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
-- grouped on year-like text/number column YEAR (NOT date-cast -- avoids the 8-digit epoch trap); LIMIT bounds it.
select "YEAR" as year, count(*) as records
from THE_LIBRARY.ENERGY_ENVIRONMENT.MINERAL_PRODUCTION_BY_COUNTRY
group by 1
order by 1
limit 1000
